class Solution {
public:
    int houseCount(Street* street, int k) {
        for (int i = 0; i < k; ++i) {
            street->openDoor();
            street->moveLeft();
        }
        int ans = 0;
        while (street->isDoorOpen()) {
            street->closeDoor();
            street->moveLeft();
            ans++;
        }
        return ans;
    }
};

class Solution {
    public int houseCount(Street street, int k) {
        for (int i = 0; i < k; i++) {
            street.openDoor();
            street.moveLeft();
        }
        int ans = 0;
        while (street.isDoorOpen()) {
            street.closeDoor();
            street.moveLeft();
            ans++;
        }
        return ans;
    }
}

